(4185, 'Skulls you will give and skulls I will take.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(4186, 'Be healed, my pets!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(4206, '', 'Well done! Without your help I would have never been able to thwart that wave of troggs.', 0, 0, 0, 4, 0, 0, 0, 0, 0),
(4207, '', 'Did you hear something?', 0, 0, 0, 6, 0, 0, 0, 0, 0),
(4208, '', 'I heard something over there.', 0, 0, 0, 25, 0, 0, 0, 0, 0),
(4209, '', 'More troggs! Ward them off as I prepare the explosives!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
