(8980, 'Now we''re making progress!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(8981, 'Thank you for the armor scraps, $n!', '', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(8982, 'Our cache of equipment grows!', '', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(8983, 'Thank you for the supplies, $n.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(8984, 'Very good.  Our supply cache grows...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
