(12355, 'Scourge spotted nearby!', 'Scourge spotted nearby!', 0, 0, 1, 5, 0, 0, 0, 0, 0),
(12356, 'I just saw a Scourge!  Kill it!', 'I just saw a Scourge!  Kill it!', 0, 0, 1, 5, 0, 0, 0, 0, 0),
(12357, 'Did you see that?  There''s a Scourge over there!', 'Did you see that?  There''s a Scourge over there!', 0, 0, 1, 5, 0, 0, 0, 0, 0),
