(563, '%s begins translating ...', '', 2, 0, 7, 0, 0, 0, 0, 0, 0),
(564, '$n, the translation is finished!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(566, 'This is a dangerous line of business!$B$BMiran just left with a delivery. He should be back in a few minutes.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(567, 'They thought I was weak.  Haha!!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
