(596, 'Search this rubble.', '', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(597, 'Find me something good, you dogs!', '', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(598, 'Over here! Inside the room. Did you find the key to my chains? The human Borhuin has them.', '', 0, 0, 1, 0, 0, 0, 0, 0, 0),
(599, 'I rise from the grave to take my revenge!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
