(601, 'The undead shall feast on your soul, $n.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(602, 'I have risen!', '', 1, 0, 0, 1, 0, 0, 0, 0, 0),
(603, 'Revenge shall be mine at last!', '', 1, 0, 0, 1, 0, 0, 0, 0, 0),
(604, 'Southshore shall pay in blood!', '', 1, 0, 0, 1, 0, 0, 0, 0, 0),
(605, 'Mmm... I love my delicious Southshore stout.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(606, 'Southshore stout, how do I love thee? Let me count the ways...', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
