(609, 'Guards! Guards!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(610, 'You''re going to pay for this outrage! Guards!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(611, 'Get to your posts! Let no invader reach Southshore!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
