(656, 'Good night, my friends. Until tomorrow.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(657, 'Can''t we just sleep a while longer?', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(658, 'Okay, okay... I''m up.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(659, '''Bout time. I was hungry an hour ago.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(660, 'Finally! I can''t wait to get some sleep tonight.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
