(678, 'Mmm, good stuff. Back to work once again.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(679, 'Another day gone by...', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(680, 'Night, night.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(681, '%s is struck dumb by the Soul Gem!', '', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(682, '%s''s spirit is freed...', '', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(683, '%s lets out a deep sigh.', '', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(684, 'I hate this part of my job. Oh Duskwood, be gentle with poor Antonio.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
