(699, '', 'Stop pulling her hair out!', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(700, '', 'You''re hurting her!', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(701, '', 'Stop! You''ll pull her head off!', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(702, 'Hello, hello, Amy. It''s good to be back in Lakeshire and to see you, milady.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
