(709, 'Crybaby! Crybaby!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(710, 'Baby wants her dolly!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(711, 'Oops!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(712, 'I''ve finally reached Lakeshire-- come one, come all, and take advantage of Antonio Perelli''s wonderful deals.', '', 0, 0, 7, 22, 0, 0, 0, 0, 0),
(713, 'Items powerful enough to help make the journey through Duskwood, Antonio Perelli''s goods are now for sale here in Lakeshire.', '', 0, 0, 7, 22, 0, 0, 0, 0, 0),
(714, 'Good to see you again, Amy. Be safe, luv. I''m off to Goldshire now.', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
