(1191, '%s goes into a frenzy!', '', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(1192, 'Ask me how to get a free drink at the Blue Recluse!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
(1193, 'Free drinks at the Blue Recluse!', '', 0, 0, 7, 0, 0, 0, 0, 0, 0),
