(4872, 'Tracking', 'Tracking', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(4873, '', 'The death of our flesh marked the birth of our spirit and our sacred task.', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(4874, 'I am one of the Seven, and it is our doom to stand sentry.  Forever.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(4875, 'Our leader, Doom''rel, has ears for the challenge.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(4876, 'I am forever denied the touch of stone.  I will never again know the glory of shaped iron...', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
