(8601, 'In Alterac Valley, battles rage and equipment is in short supply.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(8602, 'I''ve reached my supply needs for now.', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(8603, 'Hook me up!', 'Hook me up!', 0, 0, 0, 0, 0, 0, 0, 0, 0),
