(8616, 'WHO DARES SUMMON LOKHOLAR?', '', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(8617, 'The blood of a thousand Alliance soldiers I shall spill... None shall stand against the might of the Ice Lord!', '', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(8618, 'I drink in your suffering, mortal. Let your essence congeal with Lokholar!', '', 1, 0, 0, 0, 0, 0, 0, 0, 0),
(8619, '%s''s death wail has stirred the nearby silithid hive!', '', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(8620, '', '%s''s death wail has stirred the nearby silithid hive!', 2, 0, 0, 0, 0, 0, 0, 0, 0),
(8621, '', 'The blood of our enemies shall be spilt upon the battlefield. The great elementals shall answer our call and crush all that stand in our way.', 0, 0, 0, 1, 0, 0, 0, 0, 0),
