(10197, 'Let''s give this a try...', '', 0, 0, 1, 28, 0, 0, 0, 0, 0),
(10198, 'I caught a fish if you are hungry...', '', 0, 0, 1, 71, 0, 0, 0, 0, 0),
(10199, '$n has assaulted the stables!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(10200, '$n has assaulted the stables!', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
