(13655, 'What promotions do you have?', 'What promotions do you have?', 0, 0, 0, 0, 0, 0, 0, 0, 0),
(13656, 'Upperdeck Promotion - Landro Default', '', 0, 0, 0, 0, 0, 0, 0, 0, 0),
